        return G

    def laplacian(G):
        n = len(G)
        D = [sum(row) for row in G]
        L = [[0] * n for _ in range(n)]
        for i in range(n):
            L[i][i] = D[i]
            for j in range(i + 1, n):
                L[i][j] = -G[i][j]
                L[j][i] = -G[j][i]
        return L

    def smallest_non_zero_eigenvalue(L):
