        eigenvalues = [0] * n
        for i in range(n):
            for j in range(n):
                if i == j:
                    eigenvalues[i] += L[i][j]
                else:
                    eigenvalues[i] -= L[i][j]
        return min(eigenvalue for eigenvalue in eigenvalues if eigenvalue != 0)

    def communication_complexity_rank(G):
        n = len(G)
        degrees = [sum(row) for row in G]
        return min(degrees)

